INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 15, 'theory', 'Quiz: graphs, traversals and connectivity');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 15, 0, 'Why does the check "vertex already visited means cycle" give false alarms on directed graphs?', '["Two paths converging on one vertex do not form a ring; a three-color detector is needed", "Because directed graphs have no cycles", "Because visited vertices cannot be marked twice", "Because the naive check is too slow"]', 0, 'An edge into a gray vertex (the current path) means a cycle, an edge into a black vertex does not. Three colors are the industry standard.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 15, 1, 'When does breadth-first search find shortest paths, and when does it lie?', '["It always finds them: waves do not make mistakes", "Only in directed graphs without loops", "Only on trees; on general graphs it always lies", "In an unweighted graph it gives the fewest steps; with different weights it lies: a wave along many short roads may weigh more than one long road"]', 3, 'For weights you need Dijkstra''s algorithm. The rule of choice: if you need any path quickly and with minimal memory, use depth; if you need the shortest in an unweighted graph, use breadth.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 15, 2, 'How does Kahn''s algorithm detect a cycle in a dependency graph?', '["It colors the vertices with three colors", "If at the end the answer is shorter than the list of vertices, the remaining ones sit in a cycle", "It compares the in-degrees of all vertices pairwise", "It runs a breadth-first search from every vertex"]', 1, 'Vertices with in-degree zero go into the queue, and processing them lowers the in-degrees of the dependents. A cycle means an inconsistent system of dependencies, and the algorithm honestly detects it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 15, 3, 'When exactly should vertices be marked as visited in breadth-first search?', '["After the whole traversal is finished", "At the moment they are taken out of the queue", "When they are put into the queue, otherwise one vertex lands there several times", "It does not matter for correctness"]', 2, 'Marking late bloats the queue and ruins the complexity. Among the same practical subtleties: deep recursion on large graphs is replaced by an explicit stack.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 15, 4, 'A social network: a million users, about a hundred friends each. How should the graph be stored?', '["With adjacency lists: memory is proportional to vertices plus edges", "With an adjacency matrix: constant-time edge checks matter more than memory", "With a sorted array of vertex pairs", "With a search tree over vertex numbers"]', 0, 'A matrix would drown in a trillion empty cells. The practical rule: dense graphs use a matrix, sparse ones (most real systems) use lists.');
